informational.CommandLine:
powershell -NoProfile -Command "
$hits = @()
Get-CimInstance Win32_Process | ForEach-Object {
  $exe = [string]$_.ExecutablePath
  $cmd = [string]$_.CommandLine
  $why = @()
  if ($exe -match 'maintenance_ci_venv|\\\.venv-broken\\') { $why += 'exe-target' }
  if ($cmd -match 'maintenance_ci_venv|venv-broken') { $why += 'cmd-target' }
  if ($_.Name -match '^(python|pythonw|python3|pytest|uvicorn|pip)(\.exe)?$') { $why += 'python-like' }
  if ($why.Count -gt 0) {
    $hits += [PSCustomObject]@{ ProcessId = $_.ProcessId; Name = $_.Name; ExecutablePath = $exe; CommandLine = $cmd; Why = ($why -join ',') }
  }
}
if ($hits.Count -eq 0) { '[]' } else { $hits | ConvertTo-Json -Compress -Depth 4 }
"
